def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    anchors = [c for c, value in enumerate(grid[-1]) if value == 5]
    for c in anchors:
        seeds = [(r, grid[r][c]) for r in range(n - 1) if grid[r][c] != 0]
        for r in range(n - 1):
            out[r][c] = 0
        for i, (r, color) in enumerate(seeds):
            upper = seeds[i - 1][0] + 1 if i else 0
            for rr in range(upper, r + 1):
                out[rr][c] = color
        out[n - 1][c] = 5
    return out
